window.__PAGE_RUNTIME_PARTIALS__["partials/guia-python-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA · FPI\u003c/div\u003e\n      \u003ch2\u003eGuía - Práctica de Python\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinformáticos · Variables, condicionales y POO\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eAvance basado en actividades entregadas (retos y ejercicios adicionales).\u003c/p\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eConceptos\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentación\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#que-es-python\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128013;\u003c/span\u003e 1. ¿Qué es Python?\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#variables\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128230;\u003c/span\u003e 2. Variables\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#condicionales\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128270;\u003c/span\u003e 3. Condicionales\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eEjercicios\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#ejercicios\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128221;\u003c/span\u003e Ejercicios 1 a 7\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#poo\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#129513;\u003c/span\u003e 4. POO (Ej. 8 a 10)\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eEntrega\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reto\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#127919;\u003c/span\u003e Reto integrador \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#python-en-linea\" onclick=\"setActive(this)\" data-python-online-practice\u003e\u003cspan class=\"icon\"\u003e\u0026#128187;\u003c/span\u003e Python en línea\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\u003cstrong\u003eGuía - Práctica de Python\u003c/strong\u003e\u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128013;\u003c/span\u003e\u003cspan\u003e10 ejercicios\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGuía complementaria · Programación\u003c/div\u003e\n        \u003ch1\u003eGuía - Práctica de Python\u003c/h1\u003e\n        \u003cp\u003e\n          10 ejercicios progresivos para entender los conceptos básicos de Python:\n          \u003cstrong\u003equé es Python, los tipos de variables más usados, cómo funcionan las\n          condicionales y cómo iniciar con Programación Orientada a Objetos (POO)\u003c/strong\u003e\n          mediante ejemplos sencillos aplicados al contexto del aprendiz.\n        \u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128013; Python · variables, condicionales y POO\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; Código: 233108 · V1\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127979; I.E. Santa Bárbara\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"python-delivery-summary\"\u003e\u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eEsta tabla se marca sola cuando entregas cada actividad a Drive\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv id=\"python-control-avance\" data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eNo tienes que marcar nada aqu\u0026iacute;: cada fila cambia a \u003cstrong\u003eEntregada\u003c/strong\u003e autom\u0026aacute;ticamente\n            cuando subes la evidencia con el bot\u0026oacute;n de cada ejercicio. Si una fila sigue en Pendiente,\n            ese ejercicio a\u0026uacute;n no tiene entrega registrada.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentación\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e3f2fd\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eMaterial de apoyo para clase\u003c/h3\u003e\u003cp\u003eDe los conceptos a la práctica con código\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\n            Esta guía sirve como material de apoyo para explicar de forma práctica qué es Python,\n            cuáles son los tipos de variables más usados, cómo funcionan las condicionales y cómo\n            iniciar con Programación Orientada a Objetos, mediante ejemplos sencillos y progresivos.\n          \u003c/p\u003e\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128161; Idea clave: la indentación es obligatoria\u003c/div\u003e\n            \u003cp\u003eEn Python, los espacios al inicio de una línea indican qué instrucciones pertenecen a un\n            bloque (por ejemplo, dentro de un \u003ccode\u003eif\u003c/code\u003e, una función o una clase). Si la indentación\n            está mal, el programa no funciona.\u003c/p\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128221; Cómo usar esta guía\u003c/div\u003e\n            \u003cp\u003eLee cada concepto, escribe y ejecuta el código sugerido en tu computador (puedes usar\n            \u003cstrong\u003eIDLE\u003c/strong\u003e, \u003cstrong\u003eThonny\u003c/strong\u003e o \u003cstrong\u003eVisual Studio Code\u003c/strong\u003e), y resuelve\n            el reto de cada ejercicio. Al final entregas el \u003cstrong\u003ereto integrador\u003c/strong\u003e.\u003c/p\u003e\n          \u003c/div\u003e\n          \u003cdiv id=\"python-en-linea\" class=\"python-lab-wrap\" data-python-online-practice\u003e\n            \u003cdiv class=\"python-lab-intro\"\u003e\n              \u003cdiv class=\"label\"\u003e\u0026#128187; Opción A · Practicar Python en línea dentro del portal\u003c/div\u003e\n              \u003cp\u003e\n                Módulo interno opcional para estudiantes que no pueden instalar programas o trabajan en equipos\n                lentos, prestados o institucionales. Permite escribir, ejecutar, validar y descargar código Python\n                sin salir del portal; no reemplaza la práctica normal ni las evidencias de la guía.\n              \u003c/p\u003e\n              \u003ca class=\"python-lab__btn python-lab__btn--primary\" href=\"practica-python.html\" style=\"display:inline-flex;align-items:center;text-decoration:none;margin-top:10px\"\u003e\n                Abrir práctica interna\n              \u003c/a\u003e\n            \u003c/div\u003e\n\n            \u003cdiv class=\"python-lab-backup\"\u003e\n              \u003cdiv class=\"label\"\u003e\u0026#128279; Opción B · Respaldo externo\u003c/div\u003e\n              \u003cp\u003eEl enlace externo que ya estaba en la guía queda solo como respaldo si el módulo interno no cubre un caso avanzado.\u003c/p\u003e\n              \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\u003e\n                Abrir Programiz como respaldo \u0026#8599;\n              \u003c/a\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 1. ¿QUÉ ES PYTHON? ══════════════ --\u003e\n      \u003cdiv id=\"que-es-python\" class=\"section-title\"\u003e1. ¿Qué es Python?\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e\u0026#128205; \u003cstrong\u003eEn esta secci\u0026oacute;n:\u003c/strong\u003e conoces el lenguaje y ves tu primer programa.\n      Solo lectura y pr\u0026aacute;ctica libre \u0026mdash; aqu\u0026iacute; no se entrega nada todav\u0026iacute;a.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8f5e9\"\u003e\u0026#128013;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eExplicación básica y elementos iniciales\u003c/h3\u003e\u003cp\u003ePara qué sirve y qué funciones usarás\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\n            \u003cstrong\u003ePython es un lenguaje de programación\u003c/strong\u003e: un idioma que usamos para darle\n            instrucciones a un computador. Escribimos esas órdenes en un archivo de texto con extensión\n            \u003ccode\u003e.py\u003c/code\u003e y el computador las ejecuta una por una, \u003cstrong\u003ede arriba hacia abajo\u003c/strong\u003e.\n          \u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003e\n            Es uno de los lenguajes más usados del mundo porque su forma de escribir es \u003cstrong\u003eclara y\n            parecida al inglés\u003c/strong\u003e: se lee casi como una receta. Por eso es ideal para empezar \u0026mdash;\n            te concentras en \u003cem\u003eresolver el problema\u003c/em\u003e y no en reglas de escritura complicadas.\n          \u003c/p\u003e\n\n          \u003cdiv class=\"info-box\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128640; ¿Para qué se usa en el mundo real?\u003c/div\u003e\n            \u003cp\u003eAutomatizar tareas repetitivas, analizar datos y generar reportes, crear páginas web y\n            aplicaciones, inteligencia artificial y chatbots, videojuegos sencillos y soluciones para\n            empresas y colegios. Plataformas como \u003cstrong\u003eYouTube, Instagram, Netflix y Spotify\u003c/strong\u003e\n            usan Python en parte de sus sistemas.\u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003ch4 style=\"margin:18px 0 6px\"\u003e\u0026#128075; Tu primer programa\u003c/h4\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003eLo más simple es mostrar un mensaje en pantalla con la función \u003ccode\u003eprint()\u003c/code\u003e:\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# mi_primer_programa.py\u003c/span\u003e\nprint(\"¡Hola! Estoy aprendiendo Python.\")\nprint(\"Programa: Sistemas Teleinformáticos\")\u003c/pre\u003e\n          \u003cp class=\"intro-text\" style=\"font-size:.9rem;margin-bottom:6px\"\u003eAl ejecutarlo, el computador escribe:\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e¡Hola! Estoy aprendiendo Python.\nPrograma: Sistemas Teleinformáticos\u003c/pre\u003e\n\n          \u003cdiv class=\"info-box green\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128161; Tres reglas para no equivocarte\u003c/div\u003e\n            \u003cp\u003e\u003cstrong\u003e1.\u003c/strong\u003e Python distingue mayúsculas de minúsculas: \u003ccode\u003eprint\u003c/code\u003e funciona,\n            \u003ccode\u003ePrint\u003c/code\u003e da error. \u0026nbsp; \u003cstrong\u003e2.\u003c/strong\u003e El texto va siempre entre comillas:\n            \u003ccode\u003e\"Hola\"\u003c/code\u003e. \u0026nbsp; \u003cstrong\u003e3.\u003c/strong\u003e La \u003cem\u003eindentación\u003c/em\u003e (los espacios al inicio de\n            una línea) es obligatoria e indica qué instrucciones pertenecen a un bloque.\u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003ch4 style=\"margin:18px 0 4px\"\u003eFunciones y elementos que usarás en toda la guía\u003c/h4\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0;font-size:.86rem\"\u003ePulsa \u003cstrong\u003e\u0026#9654; probar\u003c/strong\u003e en cada uno para ver el ejemplo escribirse y su resultado (o espera: se ejecutan solos al aparecer).\u003c/p\u003e\n          \u003cdiv class=\"fn-demos\" data-fn-demos\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"print\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003eprint()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eMuestra información en pantalla.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"input\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003einput()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003ePide al usuario que escriba un dato (lo recibe como texto).\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"int\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003eint()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eConvierte un dato a número entero.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"float\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003efloat()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eConvierte un dato a número decimal.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"str\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003estr()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eConvierte un dato a texto.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"bool\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003ebool()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eRepresenta un valor lógico: verdadero o falso.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"type\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003etype()\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eIndica qué tipo de dato tiene una variable.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"comentario\"\u003e\n              \u003cdiv class=\"fn-row__head\"\u003e\n                \u003ccode class=\"fn-row__name\"\u003e# comentario\u003c/code\u003e\n                \u003cspan class=\"fn-row__desc\"\u003eExplica el código; Python no lo ejecuta.\u003c/span\u003e\n                \u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"fn-row__console\"\u003e\n                \u003cdiv class=\"fn-row__line\"\u003e\u003cspan class=\"fn-row__prompt\"\u003e\u0026gt;\u0026gt;\u0026gt;\u003c/span\u003e \u003cspan class=\"fn-row__typed\" data-fn-typed\u003e\u003c/span\u003e\u003cspan class=\"fn-row__caret\"\u003e\u003c/span\u003e\u003c/div\u003e\n                \u003cdiv class=\"fn-row__out\" data-fn-result\u003e\u003c/div\u003e\n              \u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128296; ¿Dónde escribo y ejecuto el código?\u003c/div\u003e\n            \u003cp\u003e\u0026#128187; \u003cstrong\u003eCon programa instalado:\u003c/strong\u003e puedes usar \u003cstrong\u003eIDLE\u003c/strong\u003e (viene con Python), \u003cstrong\u003eThonny\u003c/strong\u003e (muy recomendado\n            para principiantes) o \u003cstrong\u003eVisual Studio Code\u003c/strong\u003e. Escribe el código, guárdalo con\n            extensión \u003ccode\u003e.py\u003c/code\u003e y ejecútalo con el botón \u003cem\u003eRun\u003c/em\u003e o la tecla \u003ccode\u003eF5\u003c/code\u003e.\u003c/p\u003e\n            \u003cp data-python-online-practice style=\"margin-top:8px\"\u003e\u0026#128187; \u003cstrong\u003eSin instalación:\u003c/strong\u003e\n            usa primero la \u003ca href=\"practica-python.html\" style=\"color:var(--primary,#1565c0);font-weight:700\"\u003eOpción A, laboratorio interno del portal\u003c/a\u003e.\n            El enlace externo queda como Opción B de respaldo si necesitas probar algo fuera del portal.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 2. VARIABLES ══════════════ --\u003e\n      \u003cdiv id=\"variables\" class=\"section-title\"\u003e2. Tipos de variables en Python\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e\u0026#128205; \u003cstrong\u003eEn esta secci\u0026oacute;n:\u003c/strong\u003e aprendes los tipos de datos (texto, n\u0026uacute;meros,\n      booleanos, colecciones) con demos animadas. Esta teor\u0026iacute;a es la base de los ejercicios 1 a 7.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#ede7f6\"\u003e\u0026#128230;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eTipos de datos\u003c/h3\u003e\u003cp\u003eTexto, números, lógicos y colecciones\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\n            Una variable es un espacio en memoria donde se guarda información. En Python no es necesario\n            escribir el tipo de dato antes de crear la variable, porque Python lo identifica según el valor asignado.\n          \u003c/p\u003e\n\n          \u003cp class=\"intro-text\" style=\"margin-bottom:8px\"\u003e\u003cstrong\u003e\u0026#9654; Pulsa \"probar\"\u003c/strong\u003e y verás a Python crear cada tipo de variable con su valor y su tipo (o se ejecutan en cascada al aparecer):\u003c/p\u003e\n          \u003cdiv class=\"fn-demos\" data-fn-demos\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_str\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003estr\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eTexto o cadena de caracteres.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_int\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003eint\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eNúmero entero.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_float\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003efloat\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eNúmero decimal.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_bool\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003ebool\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eValor lógico: True o False.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_list\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003elist\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eLista ordenada y modificable.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_tuple\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003etuple\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eColección ordenada que no se modifica.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_dict\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003edict\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eDiccionario con clave y valor.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_set\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003eset\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eConjunto sin datos repetidos.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"var_none\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003eNone\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eRepresenta ausencia de valor.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Recomendación\u003c/div\u003e\n            \u003cp\u003eAntes de las condicionales, diferencia entre texto, número entero, número decimal y valor\n            lógico: los errores más comunes ocurren al comparar datos de tipos diferentes.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 3. CONDICIONALES ══════════════ --\u003e\n      \u003cdiv id=\"condicionales\" class=\"section-title\"\u003e3. Operadores y condicionales\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e\u0026#128205; \u003cstrong\u003eEn esta secci\u0026oacute;n:\u003c/strong\u003e aprendes a comparar valores y a que tu programa\n      tome decisiones con if / elif / else. La usar\u0026aacute;s en casi todos los ejercicios.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff3e0\"\u003e\u0026#128270;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eComparación, lógicos y tipos de condicional\u003c/h3\u003e\u003cp\u003ePara que el programa tome decisiones\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\n            Las condicionales permiten que un programa tome decisiones: ejecutan una acción solo si se\n            cumple una condición.\n          \u003c/p\u003e\n          \u003ch4 style=\"margin:14px 0 6px\"\u003eOperadores de comparación \u003cspan style=\"font-weight:400;font-size:.82rem;color:#64748b\"\u003e(dan True o False) \u0026mdash; pulsa \"probar\"\u003c/span\u003e\u003c/h4\u003e\n          \u003cdiv class=\"fn-demos\" data-fn-demos\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"op_eq\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003e==\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eIgual a\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"op_ne\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003e!=\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eDiferente de\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"op_gt\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003e\u0026gt;\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eMayor que\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"op_lt\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003e\u0026lt;\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eMenor que\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"op_ge\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003e\u0026gt;=\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eMayor o igual que\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"op_le\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003e\u0026lt;=\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eMenor o igual que\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003ch4 style=\"margin:16px 0 6px\"\u003eOperadores lógicos \u003cspan style=\"font-weight:400;font-size:.82rem;color:#64748b\"\u003e(combinan condiciones) \u0026mdash; pulsa \"probar\"\u003c/span\u003e\u003c/h4\u003e\n          \u003cdiv class=\"fn-demos\" data-fn-demos\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"log_and\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003eand\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eTodas las condiciones deben cumplirse.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"log_or\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003eor\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eAl menos una condición debe cumplirse.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n            \u003cdiv class=\"fn-row\" data-fn=\"log_not\"\u003e\u003cdiv class=\"fn-row__head\"\u003e\u003ccode class=\"fn-row__name\"\u003enot\u003c/code\u003e\u003cspan class=\"fn-row__desc\"\u003eNiega una condición.\u003c/span\u003e\u003cbutton type=\"button\" class=\"fn-row__play\" data-fn-play\u003e\u0026#9654; probar\u003c/button\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003ch4 style=\"margin:16px 0 6px\"\u003eTipos de condicionales\u003c/h4\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\u003ctr\u003e\u003cth\u003eTipo\u003c/th\u003e\u003cth\u003eCuándo se usa\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003ccode\u003eif\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eCuando solo se necesita validar una condición.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003ccode\u003eif - else\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eCuando hay dos caminos posibles.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003ccode\u003eif - elif - else\u003c/code\u003e\u003c/td\u003e\u003ctd\u003eCuando hay varias opciones.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCondicional anidada\u003c/td\u003e\u003ctd\u003eCuando una condición depende de otra.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCondición compuesta\u003c/td\u003e\u003ctd\u003eCuando se combinan condiciones con and/or.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCondicional ternaria\u003c/td\u003e\u003ctd\u003ePara una decisión corta en una línea.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003e\u003ccode\u003ematch - case\u003c/code\u003e\u003c/td\u003e\u003ctd\u003ePara evaluar varias opciones de forma ordenada.\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#9888; Nota sobre match-case\u003c/div\u003e\n            \u003cp\u003eLa estructura \u003ccode\u003ematch-case\u003c/code\u003e está disponible desde Python 3.10. Si el computador usa\n            una versión anterior, se puede reemplazar por \u003ccode\u003eif\u003c/code\u003e, \u003ccode\u003eelif\u003c/code\u003e y \u003ccode\u003eelse\u003c/code\u003e.\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ EJERCICIOS 1–7 ══════════════ --\u003e\n      \u003cdiv id=\"ejercicios\" class=\"section-title\"\u003eEjercicios prácticos (1 a 7)\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e\u0026#128205; \u003cstrong\u003eEn esta secci\u0026oacute;n:\u003c/strong\u003e 7 ejercicios guiados. Cada uno tiene un\n      \u003cstrong\u003eReto\u003c/strong\u003e y un \u003cstrong\u003eEjercicio adicional\u003c/strong\u003e que se entregan a Drive (son tus evidencias).\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e\u0026#129517; \u0026iquest;C\u0026oacute;mo trabajar cada ejercicio? Son siempre los mismos 5 pasos\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee el objetivo y el enunciado.\u003c/strong\u003e Ah\u0026iacute; dice qu\u0026eacute; hace el programa y qu\u0026eacute; conceptos practica.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEscribe el c\u0026oacute;digo de ejemplo\u003c/strong\u003e en la \u003ca href=\"practica-python.html\"\u003econsola Python del portal\u003c/a\u003e. Escr\u0026iacute;belo t\u0026uacute; mismo en lugar de copiar y pegar: as\u0026iacute; es como se aprende.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEjec\u0026uacute;talo y compara\u003c/strong\u003e el resultado con lo que esperabas. Si sale un error, l\u0026eacute;elo con calma: te dice en qu\u0026eacute; l\u0026iacute;nea est\u0026aacute; el problema.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve el Reto y el Ejercicio adicional\u003c/strong\u003e modificando el c\u0026oacute;digo por tu cuenta. La explicaci\u0026oacute;n de cada ejercicio te sirve de ejemplo, pero la soluci\u0026oacute;n es tuya.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega la evidencia\u003c/strong\u003e (captura de pantalla o archivo .py) con el bot\u0026oacute;n \u003cem\u003eEntregar actividad a Drive\u003c/em\u003e que hay en cada ejercicio.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n        \u003cp\u003eNo necesitas instalar nada: todo se puede hacer en la consola del portal. Equivocarse hace parte de\n        programar \u0026mdash; cada error que corriges es algo que aprendiste.\u003c/p\u003e\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e0f2f1\"\u003e\u0026#128221;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eVariables y condicionales\u003c/h3\u003e\u003cp\u003e7 ejercicios progresivos con código y explicación\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eRegistro básico del aprendiz\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e identificar variables tipo texto, entero, decimal y booleano.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003estr, int, float, bool, print(), type()\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e crear un programa que registre los datos básicos de un aprendiz y muestre el tipo de dato de cada variable.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 1: Registro básico del aprendiz\u003c/span\u003e\nnombre = \"Laura Gómez\"\nedad = 16\npromedio = 4.2\nmatriculado = True\n\nprint(\"=== DATOS DEL APRENDIZ ===\")\nprint(\"Nombre:\", nombre)\nprint(\"Edad:\", edad)\nprint(\"Promedio:\", promedio)\nprint(\"¿Está matriculado?:\", matriculado)\nprint()\nprint(\"=== TIPOS DE DATOS ===\")\nprint(type(nombre))\nprint(type(edad))\nprint(type(promedio))\nprint(type(matriculado))\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003e\u003ccode\u003enombre\u003c/code\u003e guarda texto → su tipo es \u003ccode\u003estr\u003c/code\u003e.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eedad\u003c/code\u003e guarda un entero → su tipo es \u003ccode\u003eint\u003c/code\u003e.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003epromedio\u003c/code\u003e guarda un decimal → su tipo es \u003ccode\u003efloat\u003c/code\u003e.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003ematriculado\u003c/code\u003e guarda True/False → su tipo es \u003ccode\u003ebool\u003c/code\u003e.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003etype()\u003c/code\u003e permite ver el tipo de dato de una variable.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eCambia los datos del aprendiz y agrega una nueva variable llamada \u003ccode\u003eficha\u003c/code\u003e.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eRegistra los datos de un \u003cstrong\u003einstructor\u003c/strong\u003e usando variables: su nombre (texto), los a\u0026ntilde;os que lleva ense\u0026ntilde;ando (entero), su salario mensual (decimal) y si est\u0026aacute; vinculado de planta o no (booleano). Muestra cada dato con \u003ccode\u003eprint()\u003c/code\u003e y al final imprime el tipo de cada variable con \u003ccode\u003etype()\u003c/code\u003e.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj1\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj1\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e2\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eEdad y condicional simple\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e usar input(), int() y una condicional if para validar una edad.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003einput(), int, if, comparación \u0026gt;=\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e pedir el nombre y la edad. Si tiene 15 años o más, mostrar que puede iniciar la formación técnica.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 2: Edad y condicional simple\u003c/span\u003e\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nedad = int(input(\"Ingrese la edad: \"))\n\nprint()\nprint(\"Aprendiz:\", nombre)\nprint(\"Edad:\", edad)\n\nif edad \u0026gt;= 15:\n    print(\"Puede iniciar la formación técnica.\")\n\nprint(\"Fin del programa.\")\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003e\u003ccode\u003einput()\u003c/code\u003e recibe datos del usuario como texto.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eint()\u003c/code\u003e convierte la edad a número entero para poder compararla.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eedad \u0026gt;= 15\u003c/code\u003e verifica si cumple la edad mínima.\u003c/li\u003e\n                \u003cli\u003eSi es verdadera, Python ejecuta el mensaje indentado debajo del \u003ccode\u003eif\u003c/code\u003e.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega una condición para mostrar un mensaje cuando la edad sea menor de 15 años.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003ePide el nombre y la nota de un aprendiz con \u003ccode\u003einput()\u003c/code\u003e. Convierte la nota a n\u0026uacute;mero decimal con \u003ccode\u003efloat()\u003c/code\u003e. Si la nota es mayor o igual a 3.5, muestra el mensaje \u003cem\u003e\"Nota aprobatoria\"\u003c/em\u003e. El programa siempre debe imprimir el nombre y la nota ingresada, sin importar el resultado.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj2\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj2\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eNota final con if y else\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e aplicar una decisión con dos resultados: aprobado o no aprobado.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003efloat, if, else, round()\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e pedir tres notas, calcular el promedio y decir si aprobó o no aprobó.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 3: Nota final con if y else\u003c/span\u003e\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nnota1 = float(input(\"Ingrese la nota 1: \"))\nnota2 = float(input(\"Ingrese la nota 2: \"))\nnota3 = float(input(\"Ingrese la nota 3: \"))\n\npromedio = (nota1 + nota2 + nota3) / 3\n\nprint()\nprint(\"=== RESULTADO ===\")\nprint(\"Aprendiz:\", nombre)\nprint(\"Promedio:\", round(promedio, 2))\n\nif promedio \u0026gt;= 3.5:\n    print(\"Estado: Aprobado\")\nelse:\n    print(\"Estado: No aprobado\")\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003e\u003ccode\u003efloat()\u003c/code\u003e se usa porque las notas pueden tener decimales.\u003c/li\u003e\n                \u003cli\u003eEl promedio se calcula sumando las tres notas y dividiendo entre 3.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eround(promedio, 2)\u003c/code\u003e muestra el promedio con dos decimales.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eelse\u003c/code\u003e se ejecuta cuando la condición del \u003ccode\u003eif\u003c/code\u003e no se cumple.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega una cuarta nota y modifica la fórmula del promedio.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003ePide dos calificaciones con \u003ccode\u003einput()\u003c/code\u003e, convi\u0026eacute;rtelas a decimal con \u003ccode\u003efloat()\u003c/code\u003e y calcula el promedio. Muestra el promedio redondeado a 2 decimales con \u003ccode\u003eround()\u003c/code\u003e. Si el promedio es mayor o igual a 3.5, muestra \u003cem\u003e\"Aprob\u0026oacute; la evaluaci\u0026oacute;n\"\u003c/em\u003e; si no, \u003cem\u003e\"No aprob\u0026oacute; la evaluaci\u0026oacute;n\"\u003c/em\u003e.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj3\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj3\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e4\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePromedio, asistencia y if-elif-else\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e usar varias condiciones para clasificar el estado académico.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003efloat, int, if, elif, else, and\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e calcular el promedio y revisar la asistencia; mostrar si aprueba, recupera, pierde por nota o por inasistencia.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 4: Promedio, asistencia y if-elif-else\u003c/span\u003e\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nnota1 = float(input(\"Ingrese la nota 1: \"))\nnota2 = float(input(\"Ingrese la nota 2: \"))\nnota3 = float(input(\"Ingrese la nota 3: \"))\nasistencia = int(input(\"Ingrese el porcentaje de asistencia: \"))\n\npromedio = (nota1 + nota2 + nota3) / 3\n\nprint()\nprint(\"=== REPORTE ACADÉMICO ===\")\nprint(\"Aprendiz:\", nombre)\nprint(\"Promedio:\", round(promedio, 2))\nprint(\"Asistencia:\", asistencia, \"%\")\n\nif asistencia \u0026lt; 75:\n    print(\"Estado: Perdió por inasistencia\")\nelif promedio \u0026gt;= 3.5 and asistencia \u0026gt;= 75:\n    print(\"Estado: Aprobado\")\nelif promedio \u0026gt;= 3.0:\n    print(\"Estado: Debe recuperar\")\nelse:\n    print(\"Estado: Perdió por nota\")\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003ePrimero se valida la asistencia, porque afecta el resultado final.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eelif\u003c/code\u003e revisa otras condiciones si la anterior no se cumplió.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eand\u003c/code\u003e exige que se cumplan dos condiciones a la vez.\u003c/li\u003e\n                \u003cli\u003eEl \u003ccode\u003eelse\u003c/code\u003e final cubre los casos restantes.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eCambia el porcentaje mínimo de asistencia de 75 a 80 y observa cómo cambia el resultado.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003ePide la cantidad de actividades entregadas (entero) y el porcentaje de asistencia (entero). Muestra el estado con \u003ccode\u003eif\u003c/code\u003e, \u003ccode\u003eelif\u003c/code\u003e, \u003ccode\u003eelse\u003c/code\u003e y \u003ccode\u003eand\u003c/code\u003e: \u003cstrong\u003e\"Destacado\"\u003c/strong\u003e si entreg\u0026oacute; 5 o m\u0026aacute;s actividades \u003cem\u003ey\u003c/em\u003e tiene 90 % o m\u0026aacute;s de asistencia · \u003cstrong\u003e\"Cumple\"\u003c/strong\u003e si entreg\u0026oacute; 5 o m\u0026aacute;s \u003cem\u003ey\u003c/em\u003e tiene al menos 75 % · \u003cstrong\u003e\"En proceso\"\u003c/strong\u003e si entreg\u0026oacute; al menos 3 · \u003cstrong\u003e\"Incompleto\"\u003c/strong\u003e en cualquier otro caso.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj4\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj4\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e5\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eControl de entrega de actividad\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e trabajar con booleanos, None y condicionales anidadas.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003ebool, None, if, else, condicional anidada\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e indicar el estado de una actividad según si fue entregada, si fue tarde y si tiene observación.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 5: Control de entrega de actividad\u003c/span\u003e\naprendiz = input(\"Nombre del aprendiz: \")\nactividad = input(\"Nombre de la actividad: \")\nentrego = input(\"¿Entregó la actividad? si/no: \").lower() == \"si\"\ntarde = False\nobservacion = None\n\nif entrego:\n    respuesta_tarde = input(\"¿La entregó tarde? si/no: \").lower()\n    if respuesta_tarde == \"si\":\n        tarde = True\n        observacion = \"Entregó fuera de la fecha establecida\"\n    else:\n        observacion = \"Entrega realizada a tiempo\"\nelse:\n    observacion = \"Actividad pendiente por entregar\"\n\nprint()\nprint(\"=== ESTADO DE LA ACTIVIDAD ===\")\nprint(\"Aprendiz:\", aprendiz)\nprint(\"Actividad:\", actividad)\nprint(\"Entregó:\", entrego)\nprint(\"Entrega tarde:\", tarde)\nprint(\"Observación:\", observacion)\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003e\u003ccode\u003eentrego\u003c/code\u003e es booleana porque solo puede ser True o False.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eNone\u003c/code\u003e se usa cuando una variable aún no tiene valor definido.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003e.lower()\u003c/code\u003e convierte la respuesta a minúscula (evita errores por SI, Si o si).\u003c/li\u003e\n                \u003cli\u003eLa condicional anidada pregunta si entregó tarde solo si entregó la actividad.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega una variable \u003ccode\u003ecalificacion\u003c/code\u003e y muéstrala solo si el aprendiz entregó.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eRegistra si un aprendiz asisti\u0026oacute; a una pr\u0026aacute;ctica de laboratorio (s\u0026iacute; o no). Si asisti\u0026oacute;, pregunta si fue puntual (s\u0026iacute; o no): si fue puntual, la observaci\u0026oacute;n es \u003cem\u003e\"Asisti\u0026oacute; a tiempo\"\u003c/em\u003e; si no, \u003cem\u003e\"Asisti\u0026oacute; tarde\"\u003c/em\u003e. Si no asisti\u0026oacute;, la observaci\u0026oacute;n queda como \u003ccode\u003eNone\u003c/code\u003e y se muestra \u003cem\u003e\"Sin registro de asistencia\"\u003c/em\u003e. Usa booleanos para \u003ccode\u003easistio\u003c/code\u003e y \u003ccode\u003epuntual\u003c/code\u003e, y muestra todos los datos al final.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj5\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj5\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e6\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eLista de actividades entregadas\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e usar listas, cantidad de elementos y verificación de pertenencia.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003elist, len(), in, or, not\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e guardar las actividades entregadas y verificar si tiene pendiente la actividad de Python.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 6: Lista de actividades entregadas\u003c/span\u003e\naprendiz = \"Carlos Pérez\"\nactividades_entregadas = [\"Inducción\", \"Variables\", \"Condicionales\"]\nactividad_revisar = \"Python\"\n\nprint(\"=== ACTIVIDADES ENTREGADAS ===\")\nprint(\"Aprendiz:\", aprendiz)\nprint(\"Actividades:\", actividades_entregadas)\nprint(\"Cantidad de actividades:\", len(actividades_entregadas))\n\nif actividad_revisar in actividades_entregadas:\n    print(\"La actividad de Python ya fue entregada.\")\nelse:\n    print(\"La actividad de Python está pendiente.\")\n\nif \"Variables\" in actividades_entregadas or \"Condicionales\" in actividades_entregadas:\n    print(\"El aprendiz ya inició la ruta de programación.\")\n\nif not \"POO\" in actividades_entregadas:\n    print(\"Todavía no ha entregado Programación Orientada a Objetos.\")\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003eUna lista guarda varios datos en una sola variable.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003elen()\u003c/code\u003e cuenta cuántos elementos tiene la lista.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003ein\u003c/code\u003e revisa si un dato está dentro de una lista.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eor\u003c/code\u003e permite que se cumpla una condición u otra; \u003ccode\u003enot\u003c/code\u003e invierte el resultado.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega la actividad \u003ccode\u003e\"Python\"\u003c/code\u003e a la lista y vuelve a ejecutar el programa.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eCrea una lista con los equipos disponibles en el sal\u0026oacute;n: \u003cem\u003e\"PC1\"\u003c/em\u003e, \u003cem\u003e\"PC2\"\u003c/em\u003e, \u003cem\u003e\"Proyector\"\u003c/em\u003e, \u003cem\u003e\"Tablet\"\u003c/em\u003e. Usando \u003ccode\u003elen()\u003c/code\u003e, \u003ccode\u003ein\u003c/code\u003e, \u003ccode\u003eor\u003c/code\u003e y \u003ccode\u003enot\u003c/code\u003e, muestra: cu\u0026aacute;ntos equipos hay en total · si \u003cem\u003e\"Proyector\"\u003c/em\u003e est\u0026aacute; disponible · si \u003cem\u003e\"PC3\"\u003c/em\u003e o \u003cem\u003e\"PC4\"\u003c/em\u003e est\u0026aacute;n disponibles · si \u003cem\u003e\"Impresora\"\u003c/em\u003e no est\u0026aacute; en la lista. Agrega un mensaje claro para cada caso.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj6\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj6\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e7\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eFicha con diccionario, conjunto y match-case\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e integrar estructuras de datos y una condicional match-case.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003edict, set, tuple, match-case, if anidado\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e guardar los datos en un diccionario, las evidencias en un conjunto y consultar con un menú.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 7: Ficha del aprendiz (dict, set, match-case)\u003c/span\u003e\naprendiz = {\n    \"nombre\": \"María Torres\",\n    \"grado\": \"10A\",\n    \"ficha\": 3441939,\n    \"promedio\": 4.1,\n    \"activo\": True\n}\nhorario = (\"Miércoles\", \"Viernes\")\nevidencias = {\"Variables\", \"Condicionales\", \"Listas\"}\n\nprint(\"=== MENÚ DE CONSULTA ===\")\nprint(\"1. Ver datos del aprendiz\")\nprint(\"2. Ver horario\")\nprint(\"3. Ver evidencias entregadas\")\nprint(\"4. Ver estado final\")\nopcion = int(input(\"Seleccione una opción: \"))\n\nmatch opcion:\n    case 1:\n        print(\"Nombre:\", aprendiz[\"nombre\"])\n        print(\"Grado:\", aprendiz[\"grado\"])\n        print(\"Ficha:\", aprendiz[\"ficha\"])\n    case 2:\n        print(\"Días de clase:\", horario)\n    case 3:\n        print(\"Evidencias:\", evidencias)\n        if \"POO\" in evidencias:\n            print(\"Ya entregó Programación Orientada a Objetos\")\n        else:\n            print(\"Tiene pendiente Programación Orientada a Objetos\")\n    case 4:\n        if aprendiz[\"activo\"] and aprendiz[\"promedio\"] \u0026gt;= 3.5:\n            print(\"Estado: Activo y aprobado\")\n        else:\n            print(\"Estado: Revisar situación académica\")\n    case _:\n        print(\"Opción no válida\")\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003eUn diccionario guarda datos con clave y valor (nombre, grado, ficha).\u003c/li\u003e\n                \u003cli\u003eUna tupla guarda datos que no se modifican, como los días de clase.\u003c/li\u003e\n                \u003cli\u003eUn conjunto \u003ccode\u003eset\u003c/code\u003e evita datos repetidos.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003ematch-case\u003c/code\u003e evalúa la opción de menú; \u003ccode\u003ecase _\u003c/code\u003e es la opción por defecto.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega una opción 5 al menú para mostrar si el aprendiz está activo o inactivo.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eCrea un diccionario con los datos de un \u003cstrong\u003ecomputador del aula\u003c/strong\u003e (marca, procesador, RAM y si est\u0026aacute; operativo), un conjunto con los programas instalados y una tupla con los horarios en que est\u0026aacute; disponible. Muestra un men\u0026uacute; con \u003ccode\u003ematch-case\u003c/code\u003e de 4 opciones: \u003cstrong\u003e1\u003c/strong\u003e ver datos del equipo · \u003cstrong\u003e2\u003c/strong\u003e ver programas instalados · \u003cstrong\u003e3\u003c/strong\u003e ver horarios · \u003cstrong\u003e4\u003c/strong\u003e ver si est\u0026aacute; operativo. Cualquier otra opci\u0026oacute;n muestra \u003cem\u003e\"Opci\u0026oacute;n no v\u0026aacute;lida\"\u003c/em\u003e.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj7\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj7\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ 4. POO ══════════════ --\u003e\n      \u003cdiv id=\"poo\" class=\"section-title\"\u003e4. Introducción a la Programación Orientada a Objetos (POO)\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e\u0026#128205; \u003cstrong\u003eEn esta secci\u0026oacute;n:\u003c/strong\u003e aprendes a crear clases y objetos (ejercicios 8, 9 y 10,\n      tambi\u0026eacute;n con entrega). Es el paso previo al reto integrador, donde unir\u0026aacute;s todo.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--importante\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#10071; Importante\u003c/div\u003e\n        \u003cp\u003eLa POO parece dif\u0026iacute;cil al principio y es normal. Idea clave: una \u003cstrong\u003eclase\u003c/strong\u003e es un molde\n        (como el formato en blanco de una ficha) y un \u003cstrong\u003eobjeto\u003c/strong\u003e es el molde ya diligenciado con datos\n        reales. Con esa idea clara, los tres ejercicios salen.\u003c/p\u003e\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#e8eaf6\"\u003e\u0026#129513;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eClases, objetos, atributos y métodos\u003c/h3\u003e\u003cp\u003eConceptos + ejercicios 8, 9 y 10\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\n            La POO permite organizar el código usando \u003cstrong\u003eclases\u003c/strong\u003e y \u003cstrong\u003eobjetos\u003c/strong\u003e. En vez\n            de tener todo el programa en instrucciones sueltas, se crean moldes que representan elementos reales\n            (por ejemplo, un estudiante, una actividad o una ficha).\n          \u003c/p\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\u003ctr\u003e\u003cth\u003eConcepto\u003c/th\u003e\u003cth\u003eExplicación sencilla\u003c/th\u003e\u003cth\u003eEjemplo\u003c/th\u003e\u003c/tr\u003e\u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eClase\u003c/td\u003e\u003ctd\u003eMolde o plantilla para crear objetos.\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eclass Estudiante:\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eObjeto\u003c/td\u003e\u003ctd\u003eElemento creado a partir de una clase.\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eestudiante1 = Estudiante(...)\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eAtributo\u003c/td\u003e\u003ctd\u003eCaracterística del objeto.\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eself.nombre\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eMétodo\u003c/td\u003e\u003ctd\u003eAcción que puede realizar el objeto.\u003c/td\u003e\u003ctd\u003e\u003ccode\u003ecalcular_promedio()\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eConstructor __init__\u003c/td\u003e\u003ctd\u003eInicializa los atributos al crear el objeto.\u003c/td\u003e\u003ctd\u003e\u003ccode\u003edef __init__(self, nombre):\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eself\u003c/td\u003e\u003ctd\u003eRepresenta el objeto actual dentro de la clase.\u003c/td\u003e\u003ctd\u003e\u003ccode\u003eself.nota1 = nota1\u003c/code\u003e\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128161; Forma sencilla de explicarlo\u003c/div\u003e\n            \u003cp\u003eUna clase es como un formulario vacío. Cuando lo llenamos con datos reales, creamos un objeto.\n            Los datos del formulario son \u003cstrong\u003eatributos\u003c/strong\u003e y las acciones que puede hacer son \u003cstrong\u003emétodos\u003c/strong\u003e.\u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e8\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePOO 1: Clase Estudiante\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e crear una clase con atributos, métodos y condicionales para obtener el estado académico.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003eclass, __init__, self, atributos, métodos, if-else\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e clase \u003ccode\u003eEstudiante\u003c/code\u003e con nombre, grado y tres notas; calcula el promedio y muestra si aprobó o no.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 8: POO 1 - Clase Estudiante\u003c/span\u003e\nclass Estudiante:\n    def __init__(self, nombre, grado, nota1, nota2, nota3):\n        self.nombre = nombre\n        self.grado = grado\n        self.nota1 = nota1\n        self.nota2 = nota2\n        self.nota3 = nota3\n\n    def calcular_promedio(self):\n        return (self.nota1 + self.nota2 + self.nota3) / 3\n\n    def obtener_estado(self):\n        promedio = self.calcular_promedio()\n        if promedio \u0026gt;= 3.5:\n            return \"Aprobado\"\n        else:\n            return \"No aprobado\"\n\n    def mostrar_informacion(self):\n        print(\"=== INFORMACIÓN DEL ESTUDIANTE ===\")\n        print(\"Nombre:\", self.nombre)\n        print(\"Grado:\", self.grado)\n        print(\"Promedio:\", round(self.calcular_promedio(), 2))\n        print(\"Estado:\", self.obtener_estado())\n\nestudiante1 = Estudiante(\"Laura Gómez\", \"10A\", 4.0, 3.8, 4.5)\nestudiante1.mostrar_informacion()\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003e\u003ccode\u003eclass Estudiante\u003c/code\u003e crea el molde para construir estudiantes.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003e__init__\u003c/code\u003e recibe los datos iniciales; \u003ccode\u003eself.nombre\u003c/code\u003e, \u003ccode\u003eself.grado\u003c/code\u003e… son atributos.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003ecalcular_promedio()\u003c/code\u003e y \u003ccode\u003eobtener_estado()\u003c/code\u003e son métodos (acciones).\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eestudiante1\u003c/code\u003e es un objeto creado a partir de la clase.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega un atributo \u003ccode\u003easistencia\u003c/code\u003e y modifica \u003ccode\u003eobtener_estado()\u003c/code\u003e para que pierda si la asistencia es menor a 75.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eCrea una clase \u003ccode\u003eComputador\u003c/code\u003e con los atributos: marca (texto), velocidad del procesador en GHz (decimal) y si est\u0026aacute; encendido (booleano). La clase debe tener un m\u0026eacute;todo que muestre la informaci\u0026oacute;n del equipo y otro que diga si el procesador es \u003cem\u003e\"R\u0026aacute;pido\"\u003c/em\u003e o \u003cem\u003e\"Lento\"\u003c/em\u003e (r\u0026aacute;pido si la velocidad es mayor o igual a 2.5 GHz). Crea dos objetos con datos distintos y muestra la informaci\u0026oacute;n de cada uno.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj8\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj8\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e9\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePOO 2: Clase EntregaActividad\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e representar una entrega académica como objeto y evaluar su estado.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003eclass, bool, None, if-elif-else, métodos\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e clase que guarde la información de una actividad entregada e indique si está pendiente, a tiempo, tarde o aprobada.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 9: POO 2 - Clase EntregaActividad\u003c/span\u003e\nclass EntregaActividad:\n    def __init__(self, aprendiz, actividad, entregada, tarde, nota=None):\n        self.aprendiz = aprendiz\n        self.actividad = actividad\n        self.entregada = entregada\n        self.tarde = tarde\n        self.nota = nota\n\n    def obtener_estado(self):\n        if not self.entregada:\n            return \"Pendiente por entregar\"\n        elif self.nota is None:\n            return \"Entregada, pendiente por calificar\"\n        elif self.tarde and self.nota \u0026gt;= 3.5:\n            return \"Aprobada, pero entregada tarde\"\n        elif self.nota \u0026gt;= 3.5:\n            return \"Aprobada\"\n        else:\n            return \"No aprobada\"\n\n    def mostrar_reporte(self):\n        print(\"=== REPORTE DE ENTREGA ===\")\n        print(\"Aprendiz:\", self.aprendiz)\n        print(\"Actividad:\", self.actividad)\n        print(\"Entregada:\", self.entregada)\n        print(\"Entrega tarde:\", self.tarde)\n        print(\"Nota:\", self.nota)\n        print(\"Estado:\", self.obtener_estado())\n\nentrega1 = EntregaActividad(\"Carlos Pérez\", \"Condicionales\", True, False, 4.2)\nentrega1.mostrar_reporte()\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003eLa clase \u003ccode\u003eEntregaActividad\u003c/code\u003e representa una evidencia académica.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eentregada\u003c/code\u003e y \u003ccode\u003etarde\u003c/code\u003e son booleanos; \u003ccode\u003enota=None\u003c/code\u003e = sin calificar.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003enot self.entregada\u003c/code\u003e verifica si no entregó; \u003ccode\u003eelif\u003c/code\u003e clasifica los estados.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eCrea tres objetos diferentes: una entrega aprobada, una pendiente y una entregada tarde.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eCrea una clase \u003ccode\u003eAsistencia\u003c/code\u003e con los atributos: nombre del aprendiz, nombre de la sesi\u0026oacute;n, si asisti\u0026oacute; (bool), si lleg\u0026oacute; tarde (bool) y justificaci\u0026oacute;n (empieza como \u003ccode\u003eNone\u003c/code\u003e). La clase debe tener un m\u0026eacute;todo que determine el estado: \u003cem\u003e\"Inasistencia\"\u003c/em\u003e si no asisti\u0026oacute; · \u003cem\u003e\"Asistencia tard\u0026iacute;a\"\u003c/em\u003e si asisti\u0026oacute; pero lleg\u0026oacute; tarde · \u003cem\u003e\"Asistencia puntual\"\u003c/em\u003e si asisti\u0026oacute; a tiempo. Crea tres objetos con casos distintos y muestra el reporte de cada uno.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj9\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj9\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"activity open\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e10\u003c/span\u003e\u003cspan class=\"activity-title\"\u003ePOO 3: Clase Ficha con lista de aprendices\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n                            \u003cdiv data-programiz-link style=\"display:none;margin-bottom:10px\"\u003e\n                \u003ca href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\"\u003e\n                  \u0026#9654; Opción B · Programiz como respaldo \u0026#8599;\n                \u003c/a\u003e\n                \u003cspan style=\"display:block;font-size:.82em;color:#555;margin-top:4px\"\u003e\u0026#128204; Respaldo externo: usa primero la Opción A interna del portal cuando esté habilitada.\u003c/span\u003e\n              \u003c/div\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003e\u003cstrong\u003eObjetivo:\u003c/strong\u003e usar una clase que contenga una lista de objetos y aplique condicionales para un reporte.\u003c/p\u003e\n              \u003cdiv class=\"info-box\"\u003e\u003cdiv class=\"label\"\u003e\u0026#129513; Conceptos\u003c/div\u003e\u003cp\u003eclass, list, objetos, for, if, métodos\u003c/p\u003e\u003c/div\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eEnunciado:\u003c/strong\u003e clase \u003ccode\u003eFicha\u003c/code\u003e que guarde varios estudiantes, muestre cuántos tiene y liste quiénes están aprobados o en revisión.\u003c/p\u003e\n\u003cpre class=\"py-code\"\u003e\u003cspan class=\"cmt\"\u003e# Ejercicio 10: POO 3 - Clase Ficha con lista de aprendices\u003c/span\u003e\nclass Estudiante:\n    def __init__(self, nombre, promedio):\n        self.nombre = nombre\n        self.promedio = promedio\n\n    def esta_aprobado(self):\n        return self.promedio \u0026gt;= 3.5\n\nclass Ficha:\n    def __init__(self, numero, programa):\n        self.numero = numero\n        self.programa = programa\n        self.estudiantes = []\n\n    def agregar_estudiante(self, estudiante):\n        self.estudiantes.append(estudiante)\n\n    def mostrar_reporte(self):\n        print(\"=== REPORTE DE FICHA ===\")\n        print(\"Ficha:\", self.numero)\n        print(\"Programa:\", self.programa)\n        print(\"Cantidad de estudiantes:\", len(self.estudiantes))\n        for estudiante in self.estudiantes:\n            if estudiante.esta_aprobado():\n                estado = \"Aprobado\"\n            else:\n                estado = \"En revisión\"\n            print(estudiante.nombre, \"- Promedio:\", estudiante.promedio, \"-\", estado)\n\nficha = Ficha(3441939, \"Sistemas Teleinformáticos\")\nficha.agregar_estudiante(Estudiante(\"Laura Gómez\", 4.3))\nficha.agregar_estudiante(Estudiante(\"Carlos Pérez\", 3.2))\nficha.agregar_estudiante(Estudiante(\"María Torres\", 3.8))\nficha.mostrar_reporte()\u003c/pre\u003e\n              \u003cp class=\"intro-text\" style=\"font-size:.9rem\"\u003e\u003cstrong\u003eExplicación:\u003c/strong\u003e\u003c/p\u003e\n              \u003cul class=\"py-list\"\u003e\n                \u003cli\u003eSe crean dos clases: \u003ccode\u003eEstudiante\u003c/code\u003e y \u003ccode\u003eFicha\u003c/code\u003e.\u003c/li\u003e\n                \u003cli\u003eLa ficha tiene número, programa y una lista de estudiantes.\u003c/li\u003e\n                \u003cli\u003e\u003ccode\u003eappend()\u003c/code\u003e agrega objetos a la lista; \u003ccode\u003efor\u003c/code\u003e recorre cada estudiante.\u003c/li\u003e\n                \u003cli\u003eLa condicional \u003ccode\u003eif\u003c/code\u003e decide si cada estudiante está aprobado o en revisión.\u003c/li\u003e\n              \u003c/ul\u003e\n              \u003cdiv class=\"info-box green\"\u003e\u003cdiv class=\"label\"\u003e\u0026#127919; Reto\u003c/div\u003e\u003cp\u003eAgrega un método \u003ccode\u003econtar_aprobados()\u003c/code\u003e que muestre cuántos estudiantes aprobaron.\u003c/p\u003e\u003c/div\u003e\n              \u003cdiv class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\"\u003e\n                \u003cdiv class=\"label\" style=\"color:#6a1b9a\"\u003e\u0026#128161; Ejercicio adicional — pi\u0026eacute;nsalo t\u0026uacute;\u003c/div\u003e\n                \u003cp\u003eCrea dos clases: \u003ccode\u003eEquipo\u003c/code\u003e (con nombre del equipo y si est\u0026aacute; operativo) y \u003ccode\u003eAula\u003c/code\u003e (con nombre del aula y una lista de equipos). La clase \u003ccode\u003eAula\u003c/code\u003e debe tener: un m\u0026eacute;todo para agregar equipos a la lista con \u003ccode\u003eappend()\u003c/code\u003e, un m\u0026eacute;todo que muestre cu\u0026aacute;ntos equipos hay en total y un m\u0026eacute;todo que recorra la lista con \u003ccode\u003efor\u003c/code\u003e y muestre solo los equipos operativos. Crea un aula con al menos cuatro equipos y llama a cada m\u0026eacute;todo.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"adicionalEj10\"\u003e\u003c/div\u003e\n              \u003cdiv data-act-std-delivery=\"retoEj10\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ RETO INTEGRADOR (ENTREGA) ══════════════ --\u003e\n      \u003cdiv id=\"reto\" class=\"section-title\"\u003e5. Reto integrador (entrega)\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e\u0026#128205; \u003cstrong\u003eEn esta secci\u0026oacute;n:\u003c/strong\u003e el proyecto final de la gu\u0026iacute;a. Una sola entrega:\n      tu programa .py funcionando + una captura del reporte que genera.\u003c/p\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\" style=\"background:#fff8e1\"\u003e\u0026#127919;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003eSistema básico de seguimiento académico\u003c/h3\u003e\u003cp\u003eAplica todo lo aprendido y entrega tu programa\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card\"\u003e\n            \u003ch3\u003e\u0026#128221; Descripción del reto\u003c/h3\u003e\n            \u003cp\u003eCrear un programa en Python que permita registrar aprendices, actividades, notas, asistencia y\n            estado de entrega. El programa debe generar un \u003cstrong\u003ereporte final\u003c/strong\u003e del aprendiz aplicando\n            variables, tipos de datos, condicionales, listas, diccionarios y POO.\u003c/p\u003e\n          \u003c/article\u003e\n\n          \u003cdiv class=\"info-box\" style=\"margin-top:14px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#9989; Requisitos mínimos\u003c/div\u003e\n            \u003cp\u003e\n              1) Clase \u003ccode\u003eAprendiz\u003c/code\u003e con nombre, grado, ficha, asistencia y lista de actividades. ·\n              2) Clase \u003ccode\u003eActividad\u003c/code\u003e con nombre, nota, estado de entrega y observación. ·\n              3) Usar \u003ccode\u003estr, int, float, bool, list, dict, set, tuple\u003c/code\u003e y \u003ccode\u003eNone\u003c/code\u003e. ·\n              4) Usar \u003ccode\u003eif\u003c/code\u003e, \u003ccode\u003eif-else\u003c/code\u003e, \u003ccode\u003eif-elif-else\u003c/code\u003e y al menos una condicional anidada. ·\n              5) Usar \u003ccode\u003eand\u003c/code\u003e, \u003ccode\u003eor\u003c/code\u003e y \u003ccode\u003enot\u003c/code\u003e. ·\n              6) Crear mínimo tres objetos \u003ccode\u003eAprendiz\u003c/code\u003e. ·\n              7) Mostrar un reporte final con promedio, asistencia, actividades pendientes y estado académico. ·\n              8) Agregar un menú con \u003ccode\u003ematch-case\u003c/code\u003e (o \u003ccode\u003eif-elif-else\u003c/code\u003e si la versión no lo permite).\n            \u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"info-box green\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128203; Reglas del reto\u003c/div\u003e\n            \u003cp\u003e\n              Si promedio \u0026gt;= 3.5 y asistencia \u0026gt;= 75 → aprueba. ·\n              Si asistencia \u0026lt; 75 → en revisión por inasistencia. ·\n              Si tiene actividades pendientes → el reporte debe mostrarlas. ·\n              Si una actividad no tiene nota → se guarda con \u003ccode\u003eNone\u003c/code\u003e y se muestra como pendiente por calificar. ·\n              Si no tiene actividades registradas → mostrar un mensaje de advertencia.\n            \u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128206; Producto esperado y nombre del archivo\u003c/div\u003e\n            \u003cp\u003eEntrega el archivo \u003cstrong\u003e.py funcionando\u003c/strong\u003e y una \u003cstrong\u003ecaptura de pantalla\u003c/strong\u003e donde\n            se vea el reporte generado. Súbelo en un solo archivo (puedes comprimir el .py y la imagen en un .zip).\n            Sugerencia de nombre: \u003ccode\u003eRetoPython_NombreAprendiz_FICHA.zip\u003c/code\u003e\u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"gnote gnote--ruta\"\u003e\n            \u003cdiv class=\"gnote__label\"\u003e\u0026#129517; \u0026iquest;C\u0026oacute;mo abordarlo sin enredarte? Orden sugerido\u003c/div\u003e\n            \u003col\u003e\n              \u003cli\u003eCrea primero la clase \u003ccode\u003eActividad\u003c/code\u003e y prueba crear una sola actividad con \u003ccode\u003eprint()\u003c/code\u003e.\u003c/li\u003e\n              \u003cli\u003eDespu\u0026eacute;s crea la clase \u003ccode\u003eAprendiz\u003c/code\u003e y agr\u0026eacute;gale su lista de actividades.\u003c/li\u003e\n              \u003cli\u003eCrea tus tres objetos \u003ccode\u003eAprendiz\u003c/code\u003e con datos diferentes (uno que apruebe, uno con inasistencia, uno con pendientes).\u003c/li\u003e\n              \u003cli\u003eArma el reporte final con los condicionales de las reglas del reto.\u003c/li\u003e\n              \u003cli\u003eAl final agrega el men\u0026uacute; con \u003ccode\u003ematch-case\u003c/code\u003e. Prueba en la consola del portal paso a paso, no todo de una vez.\u003c/li\u003e\n            \u003c/ol\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box\" style=\"margin-top:12px\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128221; Criterios de evaluación\u003c/div\u003e\n            \u003cp\u003eFuncionamiento del programa, uso correcto de variables, uso correcto de condicionales, aplicación\n            de POO, claridad del código, orden en la presentación y evidencia de prueba.\u003c/p\u003e\n          \u003c/div\u003e\n\n          \u003cdiv class=\"gnote gnote--importante\"\u003e\n            \u003cdiv class=\"gnote__label\"\u003e\u0026#128221; \u0026iquest;C\u0026oacute;mo se eval\u0026uacute;a? (en palabras simples)\u003c/div\u003e\n            \u003cul\u003e\n              \u003cli\u003e\u003cstrong\u003eQue funcione:\u003c/strong\u003e el programa corre completo, sin errores, y muestra el reporte final.\u003c/li\u003e\n              \u003cli\u003e\u003cstrong\u003eQue use lo aprendido:\u003c/strong\u003e variables, condicionales, listas, diccionarios y las clases con sus objetos.\u003c/li\u003e\n              \u003cli\u003e\u003cstrong\u003eQue se entienda:\u003c/strong\u003e nombres de variables claros y c\u0026oacute;digo ordenado (la indentaci\u0026oacute;n cuenta).\u003c/li\u003e\n              \u003cli\u003e\u003cstrong\u003eQue haya evidencia:\u003c/strong\u003e el archivo .py y la captura donde se vea el reporte funcionando.\u003c/li\u003e\n            \u003c/ul\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--entrega\"\u003e\n            \u003cdiv class=\"gnote__label\"\u003e\u0026#128230; Antes de entregar, revisa esta lista\u003c/div\u003e\n            \u003cul\u003e\n              \u003cli\u003eEl programa corre de principio a fin sin errores.\u003c/li\u003e\n              \u003cli\u003eCumple los 8 requisitos m\u0026iacute;nimos del recuadro de arriba.\u003c/li\u003e\n              \u003cli\u003eLa captura muestra el reporte final ya generado.\u003c/li\u003e\n              \u003cli\u003eEl archivo se llama \u003ccode\u003eRetoPython_TuNombre_FICHA.zip\u003c/code\u003e (el .py y la imagen van dentro).\u003c/li\u003e\n            \u003c/ul\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"activity open mission-card\" style=\"margin-top:16px\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e5.1\u003c/span\u003e\u003cspan class=\"activity-title\"\u003eEntrega del reto integrador (.py + captura)\u003c/span\u003e\u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\" style=\"margin-top:0\"\u003eSube tu programa \u003ccode\u003e.py\u003c/code\u003e funcionando y la captura del reporte que genera. El archivo se guarda automáticamente en la carpeta de tu ficha.\u003c/p\u003e\n              \u003cdiv data-act-std-delivery=\"retoPython\"\u003e\u003c/div\u003e\n              \u003cdiv id=\"retoPythonGradeMount\" style=\"margin-top:12px\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ══════════════ GLOSARIO ══════════════ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario rápido\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\u003cdiv class=\"card-icon\" style=\"background:#f3e5f5\"\u003e\u0026#128214;\u003c/div\u003e\u003cdiv\u003e\u003ch3\u003eGlosario\u003c/h3\u003e\u003cp\u003eTérminos clave de la guía\u003c/p\u003e\u003c/div\u003e\u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary\"\u003e\n            \u003cdt\u003eVariable\u003c/dt\u003e\u003cdd\u003eEspacio donde se guarda un dato.\u003c/dd\u003e\n            \u003cdt\u003eDato\u003c/dt\u003e\u003cdd\u003eInformación que puede ser texto, número, verdadero/falso o una colección.\u003c/dd\u003e\n            \u003cdt\u003eCondicional\u003c/dt\u003e\u003cdd\u003eEstructura que permite tomar decisiones en el programa.\u003c/dd\u003e\n            \u003cdt\u003eIndentación\u003c/dt\u003e\u003cdd\u003eEspacios al inicio de una línea que indican pertenencia a un bloque.\u003c/dd\u003e\n            \u003cdt\u003eLista\u003c/dt\u003e\u003cdd\u003eColección ordenada y modificable de datos.\u003c/dd\u003e\n            \u003cdt\u003eDiccionario\u003c/dt\u003e\u003cdd\u003eColección que guarda datos con clave y valor.\u003c/dd\u003e\n            \u003cdt\u003eClase\u003c/dt\u003e\u003cdd\u003eMolde para crear objetos.\u003c/dd\u003e\n            \u003cdt\u003eObjeto\u003c/dt\u003e\u003cdd\u003eElemento creado a partir de una clase.\u003c/dd\u003e\n            \u003cdt\u003eAtributo\u003c/dt\u003e\u003cdd\u003eCaracterística de un objeto.\u003c/dd\u003e\n            \u003cdt\u003eMétodo\u003c/dt\u003e\u003cdd\u003eAcción que puede realizar un objeto.\u003c/dd\u003e\n          \u003c/dl\u003e\n          \u003cp class=\"intro-text\" style=\"font-size:.82rem;color:#607d8b;margin-top:12px\"\u003eMaterial de apoyo de Python — Programa Sistemas Teleinformáticos (233108 · V1), I.E. Santa Bárbara.\u003c/p\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
